/**
 * Schema-agnostic field model: the IR every schema provider produces and
 * the AutoForm engine consumes.
 *
 * Providers (protobuf today; Zod/Valibot/ArkType later) parse their native
 * schema into `ParsedSchema` and populate `FieldRenderHints` from whatever
 * metadata their ecosystem carries (proto annotations, schema descriptions,
 * library-specific registries). The rendering engine reads ONLY this model,
 * never provider-native handles. Provider-native data (for example proto
 * descriptors and validation rules) stays in `FieldConfig.customData`,
 * which only provider-specific code may interpret.
 */

/** A conditional UI rule evaluated against current form values (CEL today). */
export interface UiRule {
  expression?: string;
  id?: string;
  message?: string;
}

export interface OptionGroup {
  label?: string;
  options: [value: string, label: string][];
}

/** Values a field label or description may hold in the schema layer. The React layer widens this with ReactNode. */
export type Renderable = string | number | boolean | null | undefined;

/** HTML input attributes forwarded to the rendered control. */
export interface InputProps {
  [attribute: string]: string | number | boolean | undefined;
}

/**
 * Provider-private data attached to a field. Only code from the provider
 * that produced the schema may interpret the remaining properties; the
 * rendering engine must not reach into this.
 */
export interface ProviderCustomData {
  /** Discriminator naming the provider that produced this field (for example "proto"). */
  source?: string;
  [key: string]: unknown;
}

/** The value bag a form works over: field names to arbitrary user input. */
export interface FormValues {
  [field: string]: unknown;
}

/** How protobuf conversion treats empty entries in a repeated string field. */
export type EmptyRepeatedStringPolicy = "discard" | "preserve";

/**
 * Render-driving metadata, independent of any schema system.
 * Everything here answers "how should this field look and behave",
 * never "how is this field validated" (validation flows through
 * Standard Schema).
 */
export interface FieldRenderHints {
  /** Explicit simple/advanced classification override. */
  advanced?: boolean;
  /** Restrict JSON/field-mask style inputs to these paths. */
  allowedPaths?: string[];
  /** Control-type override; a key into the consumer's control registry. */
  control?: string;
  /** Named data source id for dropdown-style controls. */
  dataProvider?: string;
  /** The schema marks this field as deprecated. */
  deprecated?: boolean;
  /** Concise one-liner shown below the input. */
  description?: string;
  disabledWhen?: UiRule[];
  docsUrl?: string;
  /** Enable file drag-and-drop into the field value. */
  dropzone?: boolean;
  /** Keep blank repeated-string rows instead of discarding them during conversion. */
  emptyRepeatedStringPolicy?: EmptyRepeatedStringPolicy;
  example?: string;
  /** Detailed help text (tooltip). */
  help?: string;
  /** HTML input `type` hint (for example `email`, `url`, `number`). */
  inputType?: string;
  /** JSON-ish payload rendering mode for structured values. */
  jsonKind?: "struct" | "value" | "listValue" | "any";
  maxItems?: number;
  maxPairs?: number;
  minItems?: number;
  minPairs?: number;
  optionGroups?: OptionGroup[];
  optionLabels?: Record<string, string>;
  placeholder?: string;
  secretScope?: string;
  sensitive?: boolean;
  /** Stepper step id this field belongs to. */
  step?: string;
  /** Label used in review/summary contexts instead of the field label. */
  summaryLabel?: string;
  /** Tri-state controls: the unset state is meaningful and selectable. */
  supportsUnset?: boolean;
  visibleWhen?: UiRule[];
}

export interface FieldConfig<
  FieldTypes = string,
  CustomData extends ProviderCustomData = ProviderCustomData,
> {
  customData?: CustomData;
  description?: Renderable;
  /** Keep blank repeated-string rows instead of discarding them during conversion. */
  emptyRepeatedStringPolicy?: EmptyRepeatedStringPolicy;
  fieldType?: FieldTypes;
  inputProps?: InputProps;
  label?: Renderable;
  order?: number;
}

export interface ParsedField<FieldTypes = string> {
  default?: unknown;
  description?: Renderable;
  fieldConfig?: FieldConfig<FieldTypes>;
  hints?: FieldRenderHints;
  key: string;
  options?: [value: string, label: string][];
  required: boolean;
  schema?: ParsedField<FieldTypes>[];
  type: string;
}

export interface ParsedSchema<FieldTypes = string> {
  fields: ParsedField<FieldTypes>[];
}

export interface SchemaValidationError {
  message: string;
  path: (string | number)[];
}

export type SchemaValidation =
  | { success: true; data: unknown }
  | { success: false; errors: SchemaValidationError[] };

export interface SchemaValidationContext {
  /** Aborted when a newer validation supersedes this run or its form unmounts. */
  signal: AbortSignal;
}

export interface SchemaProvider<Values extends FormValues = FormValues> {
  getDefaultValues: () => FormValues;
  parseSchema: () => ParsedSchema;
  validateSchema: (
    values: Values,
    context?: SchemaValidationContext
  ) => SchemaValidation | Promise<SchemaValidation>;
}

/** Read a field's render hints; single accessor so call sites never reach into provider customData. */
export function getFieldHints<FieldTypes>(
  field: ParsedField<FieldTypes>
): FieldRenderHints | undefined {
  return field.hints;
}

import type { StandardSchemaV1 } from "@standard-schema/spec";

export type FormValidationErrorValue =
  | FormValidationErrors
  | FormValidationErrorValue[]
  | string
  | undefined;

/** Nested error shape consumed by Formik and Final Form. */
export interface FormValidationErrors {
  [key: string]: FormValidationErrorValue;
  [key: number]: FormValidationErrorValue;
  [key: symbol]: FormValidationErrorValue;
}

/** Configure Standard Schema validation and form-library error mapping. */
export interface FormValidatorOptions extends StandardSchemaV1.Options {
  /** Override the library-specific key used for issues without a field path. */
  rootErrorKey?: PropertyKey;
}

export type FormValidator<Input> = (
  values: Input
) => FormValidationErrors | Promise<FormValidationErrors>;

type ErrorContainer = FormValidationErrors | FormValidationErrorValue[];

function isPromiseLike<T>(value: unknown): value is PromiseLike<T> {
  return (
    (typeof value === "object" || typeof value === "function") &&
    value !== null &&
    typeof Reflect.get(value, "then") === "function"
  );
}

function isErrorContainer(value: unknown): value is ErrorContainer {
  return typeof value === "object" && value !== null;
}

function readOwn(container: ErrorContainer, key: PropertyKey): unknown {
  return Object.hasOwn(container, key)
    ? Reflect.get(container, key)
    : undefined;
}

function writeOwn(
  container: ErrorContainer,
  key: PropertyKey,
  value: FormValidationErrorValue
) {
  Object.defineProperty(container, key, {
    configurable: true,
    enumerable: true,
    value,
    writable: true,
  });
}

function appendMessage(
  container: ErrorContainer,
  key: PropertyKey,
  message: string
) {
  const current = readOwn(container, key);
  if (typeof current === "string") {
    const messages = current.split("\n");
    writeOwn(
      container,
      key,
      messages.includes(message) ? current : `${current}\n${message}`
    );
    return;
  }
  if (isErrorContainer(current)) {
    appendMessage(current, "_error", message);
    return;
  }
  writeOwn(container, key, message);
}

function getPathKey(
  segment: PropertyKey | StandardSchemaV1.PathSegment
): PropertyKey {
  return typeof segment === "object" ? segment.key : segment;
}

function createContainer(nextKey: PropertyKey): ErrorContainer {
  return typeof nextKey === "number" ? [] : {};
}

function addIssue(
  errors: FormValidationErrors,
  issue: StandardSchemaV1.Issue,
  rootErrorKey: PropertyKey
) {
  const path = issue.path?.map(getPathKey) ?? [];
  if (path.length === 0) {
    appendMessage(errors, rootErrorKey, issue.message);
    return;
  }

  let container: ErrorContainer = errors;
  for (let index = 0; index < path.length; index += 1) {
    const key = path[index];
    if (key === undefined) {
      return;
    }
    if (index === path.length - 1) {
      appendMessage(container, key, issue.message);
      return;
    }

    const nextKey = path[index + 1];
    if (nextKey === undefined) {
      return;
    }
    const current = readOwn(container, key);
    if (isErrorContainer(current)) {
      container = current;
      continue;
    }

    const next = createContainer(nextKey);
    if (typeof current === "string") {
      appendMessage(next, "_error", current);
    }
    writeOwn(container, key, next);
    container = next;
  }
}

/** Convert every Standard Schema issue into a nested, prototype-safe form error tree. */
export function standardSchemaIssuesToFormErrors(
  issues: readonly StandardSchemaV1.Issue[],
  options?: FormValidatorOptions
): FormValidationErrors {
  const errors: FormValidationErrors = {};
  const rootErrorKey = options?.rootErrorKey ?? "_error";
  for (const issue of issues) {
    addIssue(errors, issue, rootErrorKey);
  }
  return errors;
}

function resultToErrors<Output>(
  result: StandardSchemaV1.Result<Output>,
  options: FormValidatorOptions | undefined
): FormValidationErrors {
  return result.issues
    ? standardSchemaIssuesToFormErrors(result.issues, options)
    : {};
}

function getStandardSchemaOptions(
  options: FormValidatorOptions | undefined
): StandardSchemaV1.Options | undefined {
  return options?.libraryOptions === undefined
    ? undefined
    : { libraryOptions: options.libraryOptions };
}

function createValidator<Input, Output>(
  schema: StandardSchemaV1<Input, Output>,
  options: FormValidatorOptions | undefined
): FormValidator<Input> {
  return (values) => {
    const result = schema["~standard"].validate(
      values,
      getStandardSchemaOptions(options)
    );
    return isPromiseLike<StandardSchemaV1.Result<Output>>(result)
      ? Promise.resolve(result).then((resolved) =>
          resultToErrors(resolved, options)
        )
      : resultToErrors(result, options);
  };
}

/** Create Formik form-level validation with `_form` as the default root error key. */
export function createFormikValidator<Input, Output>(
  schema: StandardSchemaV1<Input, Output>,
  options?: FormValidatorOptions
): FormValidator<Input> {
  return createValidator(schema, {
    ...options,
    rootErrorKey: options?.rootErrorKey ?? "_form",
  });
}

/** Create Final Form whole-record validation. Pass Final Form's `FORM_ERROR` as `rootErrorKey`. */
export function createFinalFormValidator<Input, Output>(
  schema: StandardSchemaV1<Input, Output>,
  options?: FormValidatorOptions
): FormValidator<Input> {
  return createValidator(schema, options);
}

import type { StandardSchemaV1 } from "@standard-schema/spec";

export type { StandardSchemaV1 } from "@standard-schema/spec";

/**
 * Narrow an unknown value to a Standard Schema v1 implementation.
 *
 * This is the seam every validation source in protoform flows through:
 * the protobuf provider exposes protovalidate+CEL as a Standard Schema,
 * and future providers (Zod, Valibot, ArkType) already conform natively.
 */
export function isStandardSchema(value: unknown): value is StandardSchemaV1 {
  if (
    (typeof value !== "object" && typeof value !== "function") ||
    value === null
  ) {
    return false;
  }
  const marker = (value as { "~standard"?: unknown })["~standard"];
  if (typeof marker !== "object" || marker === null) {
    return false;
  }
  const props = marker as Partial<StandardSchemaV1.Props>;
  return (
    props.version === 1 &&
    typeof props.vendor === "string" &&
    typeof props.validate === "function"
  );
}
